            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "Задумавшиеся деревья, задористые лучи, в оврагах - ревущие ревмя всклокоченные ручьи. На ветра скрещённых саблях сложил свою голову снег, и свищет отходную зяблик зиме уходящей вослед.", Author = "Николай Асеев" },
