            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "Что выделывают птицы! Сотни радостных рулад, эхо по лесу катится, ели ухом шевелят...", Author = "Николай Асеев" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "Хорошо, что были вы живы, громкозвучный, смелый, большой; никогда не бывали лживы, никогда не кривили душой. С вами весело было смеяться, с вами неба - синей синева; с вами нечего было бояться отставать или унывать.", Author = "Николай Асеев" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "Зверинец яростных людей! Пустыня раскалённая! Читатель, в ужасе седей: вот правда не салонная.", Author = "Николай Асеев" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "Не слышит, но не сдаётся. Не пишет, но издаётся.", Author = "Николай Асеев" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "Из четырёх времён в году весна милей и ярче всех: с полей последний сходит снег, и почки пучатся в саду.", Author = "Николай Асеев" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "Снег и снег, и ель в снегу - в белых пачках - балериной, снег зажёгся на лугу ювелирною витриной.", Author = "Николай Асеев" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "Хорошо, что были вы живы, громкозвучный, смелый, большой; никогда не бывали лживы, никогда не кривили душой.", Author = "Николай Асеев" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "Люди! Бедные, бедные люди! Как вам скучно жить без стихов, без иллюзий и без прелюдий, в мире счётных машин и станков!", Author = "Николай Асеев" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Николай_Николаевич_Асеев", Text = "В конце концов всё дело в том, что мы, как все до нас, умрём. Матрос пьёт ром, больной пьёт бром, но каждый думает о том.", Author = "Николай Асеев" },
